public static int[][] solve(int[][] map) {
    int m = map.length, n = map[0].length;
    int[][] res = new int[m][n];
    int[] dr = {-1,-1,-1,0,0,1,1,1};
    int[] dc = {-1,0,1,-1,1,-1,0,1};
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (map[r][c] == 9) {
                res[r][c] = 9;
                continue;
            }
            int bombs = 0;
            for (int i = 0; i < 8; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr>=0 && nr<m && nc>=0 && nc<n && map[nr][nc] == 9) bombs++;
            }
            res[r][c] = bombs;
        }
    }
    return res;
}

