static int countCloseIsland(int[][] map) {
    int cnt = 0;
    int m = map.length;
    int n = map[0].length;

    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (map[r][c] == 1) {
                // เช็คขอบตาราง ถ้าอยู่ขอบถือว่าไม่ได้ล้อมรอบด้วยน้ำ 8 ทิศ
                if (r - 1 < 0 || r + 1 >= m || c - 1 < 0 || c + 1 >= n) continue;

                // เช็ค 4 ทิศหลัก (บน, ล่าง, ซ้าย, ขวา)
                if (map[r - 1][c] == 1 || map[r + 1][c] == 1 || map[r][c - 1] == 1 || map[r][c + 1] == 1) continue;

                // เช็ค 4 ทิศแนวทแยง
                if (map[r - 1][c - 1] == 1 || map[r + 1][c + 1] == 1 || map[r - 1][c + 1] == 1 || map[r + 1][c - 1] == 1) continue;

                cnt++;
            }
        }
    }
    return cnt;
}

