static int Xsum(int[][] arr) {
    int sum = 0;
    int m = arr.length;
    int n = arr.length;

    for (int i = 0; i < m; i++) {
        sum += arr[i][i];
    }

    for (int i = 0; i < n; i++) {
        sum += arr[m - 1 - i][i];
    }

    if (m % 2 == 1) {
        sum -= arr[m / 2][n / 2];
    }

    return sum;
}

