static int MaximumSubarraySum(int[] arr) {
    int max = Integer.MIN_VALUE;
    int sum = 0;

    for (int r = 0; r < arr.length; r++) {
        sum += arr[r];

        if (sum > max) {
            max = sum;
        }

        if (sum < 0) {
            sum = 0;
        }
    }

    return max;
}

