static void MoveZeroes(int[] arr) {
    int l = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] != 0) {
            int temp = arr[i];
            arr[i] = arr[l];
            arr[l] = temp;
            l++;
        }
    }
}
